import React from 'react';

const ProductImage = ({ image, category, name, description, sizeRange }) => {
  return (
    <div className="relative h-96 overflow-hidden rounded-t-lg">
      <img
        src={image}
        alt={name}
        className="w-full h-full object-cover"
      />
      <div className="absolute inset-0 bg-gradient-to-t from-black via-transparent to-transparent opacity-60"></div>
      <div className="absolute bottom-0 left-0 right-0 p-8 text-white">
        <p className="text-sm tracking-[0.2em] mb-2 text-[#f4d03f]">
          {category}
        </p>
        <h2 className="text-4xl font-light mb-3">{name}</h2>
        {description && (
          <p className="text-lg text-gray-200 mb-2">{description}</p>
        )}
        {sizeRange && (
          <p className="text-lg font-semibold text-white bg-[#f4d03f] bg-opacity-80 inline-block px-4 py-2 rounded">
            Size Range: {sizeRange}
          </p>
        )}
      </div>
    </div>
  );
};

export default ProductImage;
